def backfill_courier_companies(apps, schema_editor):
    """Give every existing store-owned courier a company to work for.

    Phase 3 moves riders from stores to delivery companies. There is no
    production data, but the dev database may hold seeded couriers: group each
    store's riders under an auto-created company owned by the store owner.
    """
    CourierProfile = apps.get_model("accounts", "CourierProfile")
    DeliveryCompany = apps.get_model("delivery", "DeliveryCompany")
    CompanyMembership = apps.get_model("delivery", "CompanyMembership")

    companies = {}
    for profile in CourierProfile.objects.select_related("store").filter(company__isnull=True):
        store = profile.store
        company = companies.get(store.pk)
        if company is None:
            base = f"{store.slug}-delivery"[:60]
            slug = base
            i = 2
            while DeliveryCompany.objects.filter(slug=slug).exists():
                suffix = f"-{i}"
                slug = f"{base[: 60 - len(suffix)]}{suffix}"
                i += 1
            company = DeliveryCompany.objects.create(
                owner_id=store.owner_id,
                slug=slug,
                name=f"{store.name} Delivery",
                status="active",
                is_accepting_jobs=True,
            )
            CompanyMembership.objects.get_or_create(
                company=company,
                user_id=store.owner_id,
                defaults={"role": "owner"},
            )
            companies[store.pk] = company
        profile.company_id = company.pk
        profile.save(update_fields=["company"])


